/* ===== V105: تغيير أسماء المخزن (العناوين والحقول) ويتغير بكل مكان ===== */
if(!settings.names||typeof settings.names!=='object') settings.names={};
let nmEdit=false;
function nmEls(){
  const out=[];
  document.querySelectorAll('#page-store .set-grid > .card').forEach(c=>{
    if(!c.id) return;
    const h=c.querySelector(':scope > h3');
    if(h){
      let t=h.querySelector('.nm-t');
      if(!t){ const tn=[...h.childNodes].find(n=>n.nodeType===3&&n.textContent.trim()); if(tn){ t=document.createElement('span'); t.className='nm-t'; tn.replaceWith(t); t.textContent=tn.textContent.trim() } }
      if(t) out.push([t,'h:'+c.id]);
    }
    [...c.querySelectorAll('label, .trow > span:first-child')].filter(l=>!l.closest('.low-row,#expRows,#riceExtraRows,[id^="sauceRows_"]')).forEach((l,i)=>{
      /* نعدل النص بس، مو المربع الي داخل الحقل */
      let t=l.querySelector(':scope > .nm-t');
      if(!t){ const tn=[...l.childNodes].find(n=>n.nodeType===3&&n.textContent.trim()); if(!tn) return; t=document.createElement('span'); t.className='nm-t'; tn.replaceWith(t); t.textContent=tn.textContent.trim() }
      out.push([t,'l:'+c.id+':'+i]);
    });
  });
  return out;
}
function nmApply(){
  nmEls().forEach(([el,k])=>{
    if(el.dataset.orig===undefined) el.dataset.orig=el.textContent;
    if(document.activeElement===el) return;
    const v=settings.names[k]; el.textContent=v||el.dataset.orig;
    el.contentEditable=nmEdit?'true':'false'; el.classList.toggle('nm-edit',nmEdit);
    el.dataset.nmk=k;
  });
}
/* اسم المادة بالتنبيهات والتقارير = عنوان مربعها بالمخزن */
function itemName(k){
  const it=LOW_ITEMS.find(i=>i[0]===k); if(!it) return k;
  const e=document.getElementById(it[2]), c=e&&e.closest('.card'), t=c&&c.querySelector(':scope > h3 .nm-t');
  return t?t.textContent.trim():it[1];
}
(function(){
  const hint=document.querySelector('#page-store .store-hint');
  const b=document.createElement('button'); b.type='button'; b.id='nmBtn'; b.className='nm-btn'; b.textContent='✎ تعديل الأسماء';
  hint.appendChild(b);
  b.addEventListener('click',()=>{
    nmEdit=!nmEdit; b.textContent=nmEdit?'✓ خلصت التعديل':'✎ تعديل الأسماء'; b.classList.toggle('on',nmEdit);
    nmApply(); if(nmEdit) toast('اضغط على أي اسم وغيره، ويتغير بكل النظام');
  });
  const pg=document.getElementById('page-store');
  /* وقت التعديل: الضغط على الاسم ما يسحب المربع ولا يسده */
  pg.addEventListener('pointerdown',e=>{ if(nmEdit&&e.target.closest('.nm-t')) e.stopPropagation() },true);
  pg.addEventListener('click',e=>{ if(nmEdit&&e.target.closest('.nm-t')){ e.stopPropagation(); e.preventDefault() } },true);
  pg.addEventListener('keydown',e=>{ if(e.target.classList&&e.target.classList.contains('nm-t')&&e.key==='Enter'){ e.preventDefault(); e.target.blur() } });
  pg.addEventListener('focusout',e=>{
    const el=e.target; if(!el.classList||!el.classList.contains('nm-t')||!el.dataset.nmk) return;
    const v=el.textContent.replace(/\s+/g,' ').trim(), k=el.dataset.nmk;
    if(!v||v===el.dataset.orig) delete settings.names[k]; else settings.names[k]=v;
    el.textContent=settings.names[k]||el.dataset.orig;
    saveAll(); try{ lowBadge() }catch(_){}
    if(document.getElementById('page-reports').classList.contains('active')) try{ renderReport() }catch(_){}
  });
  nmApply();
})();
